package com.wipro.hibernate;import org.hibernate.*;public class Main{public static void main(String[]a){try(Session s=HibernateUtil.getSessionFactory().openSession()){Transaction t=s.beginTransaction();s.persist(new CarDetail("KL-071","AB 123 Polo","White","Volkswagen"));s.persist(new CarDetail("KL-072","AB 234 Vento","Black","Volkswagen"));s.persist(new CarDetail("KL-073","AC 345 Corolla","Silver","Toyota"));t.commit();System.out.println("3 car records inserted.");}HibernateUtil.getSessionFactory().close();}}